class Counter:
    def **init**(self, n):
        self.n = n
    def **iter**(self):
        return self
    def **next**(self):
        if self.n == 0:
            raise StopIteration
        self.n -= 1
        return self.n

c = Counter(3)
print(list(c), list(c))

